package com.cricket.platform.tournament;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Positive;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.Authentication;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import java.time.LocalDate;
import java.time.OffsetDateTime;
import java.util.*;

@RestController
@RequestMapping("/api/tournaments")
public class TournamentController {
 private final JdbcTemplate jdbc; private final TournamentPlayoffService playoffService; public TournamentController(JdbcTemplate jdbc){this.jdbc=jdbc;this.playoffService=new TournamentPlayoffService(jdbc);}
 @GetMapping("/mine") List<TournamentView> mine(Authentication a){UUID o=ownerId(a);return jdbc.query("SELECT id,name,format,overs,location,start_date,status,created_at FROM tournaments t WHERE t.owner_id=? OR EXISTS (SELECT 1 FROM tournament_staff ts WHERE ts.tournament_id=t.id AND ts.user_id=? AND ts.role='MANAGER') ORDER BY created_at DESC",(r,n)->new TournamentView(r.getObject("id",UUID.class),r.getString("name"),r.getString("format"),r.getInt("overs"),r.getString("location"),r.getObject("start_date",LocalDate.class),r.getString("status"),r.getObject("created_at").toString()),o,o);}
 @PostMapping TournamentView create(@Valid @RequestBody CreateRequest q,Authentication a){UUID o=ownerId(a),id=UUID.randomUUID();jdbc.update("INSERT INTO tournaments(id,name,format,overs,location,start_date,status,owner_id) VALUES (?,?,?,?,?,?,?,?)",id,q.name().trim(),q.format().trim().toUpperCase(Locale.ROOT),q.overs(),blank(q.location()),q.startDate(),"DRAFT",o);return get(id,a);}
 @GetMapping("/{id}") TournamentView get(@PathVariable UUID id,Authentication a){requireOwner(id,a);return jdbc.queryForObject("SELECT id,name,format,overs,location,start_date,status,created_at FROM tournaments WHERE id=?",(r,n)->new TournamentView(r.getObject("id",UUID.class),r.getString("name"),r.getString("format"),r.getInt("overs"),r.getObject("location",String.class),r.getObject("start_date",LocalDate.class),r.getString("status"),r.getObject("created_at").toString()),id);}
 @PatchMapping("/{id}") @Transactional TournamentView update(@PathVariable UUID id,@Valid @RequestBody UpdateRequest q,Authentication a){requireOwner(id,a);ensureTournamentEditable(id);String format=q.format().trim().toUpperCase(Locale.ROOT);if(!Set.of("T10","T20","ODI","TEST").contains(format))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unsupported tournament format");jdbc.update("UPDATE tournaments SET name=?,format=?,overs=?,location=?,start_date=? WHERE id=?",q.name().trim(),format,q.overs(),blank(q.location()),q.startDate(),id);return get(id,a);}
 @PatchMapping("/{id}/status") @Transactional TournamentView changeStatus(@PathVariable UUID id,@Valid @RequestBody StatusRequest q,Authentication a){requireOwner(id,a);String current=jdbc.queryForObject("SELECT status FROM tournaments WHERE id=?",String.class,id);String target=q.status().trim().toUpperCase(Locale.ROOT);validateTransition(current,target,id);jdbc.update("UPDATE tournaments SET status=? WHERE id=?",target,id);return get(id,a);}
 @GetMapping("/{id}/teams") List<TeamView> teams(@PathVariable UUID id,Authentication a){requireOwner(id,a);return jdbc.query("SELECT t.id,t.name,t.city,tt.seed FROM tournament_teams tt JOIN teams t ON t.id=tt.team_id WHERE tt.tournament_id=? ORDER BY COALESCE(tt.seed,999),t.name",(r,n)->new TeamView(r.getObject("id",UUID.class),r.getString("name"),r.getString("city"),r.getObject("seed",Integer.class)),id);}
 @PostMapping("/{id}/teams/{teamId}") TeamView addTeam(@PathVariable UUID id,@PathVariable UUID teamId,Authentication a){requireOwner(id,a);ensureTournamentEditable(id);try{jdbc.update("INSERT INTO tournament_teams(tournament_id,team_id,seed) VALUES (?,?,(SELECT COALESCE(MAX(seed),0)+1 FROM tournament_teams WHERE tournament_id=?))",id,teamId,id);}catch(DataIntegrityViolationException e){throw new ResponseStatusException(HttpStatus.CONFLICT,"Team is already added to this tournament");}return jdbc.queryForObject("SELECT t.id,t.name,t.city,tt.seed FROM tournament_teams tt JOIN teams t ON t.id=tt.team_id WHERE tt.tournament_id=? AND tt.team_id=?",(r,n)->new TeamView(r.getObject("id",UUID.class),r.getString("name"),r.getString("city"),r.getObject("seed",Integer.class)),id,teamId);}
 @DeleteMapping("/{id}/teams/{teamId}") void removeTeam(@PathVariable UUID id,@PathVariable UUID teamId,Authentication a){requireOwner(id,a);ensureTournamentEditable(id);ensureTeamCanBeRemoved(id,teamId);jdbc.update("DELETE FROM tournament_teams WHERE tournament_id=? AND team_id=?",id,teamId);}
 @PostMapping("/{id}/matches/{matchId}") FixtureView addMatch(@PathVariable UUID id,@PathVariable UUID matchId,@RequestParam(defaultValue="LEAGUE") String stage,Authentication a){requireOwner(id,a);ensureTournamentEditable(id);String normalizedStage=normalizeStage(stage);Integer ok=jdbc.queryForObject("SELECT COUNT(*) FROM matches m JOIN tournament_teams x ON x.tournament_id=? AND x.team_id=m.team_a_id JOIN tournament_teams y ON y.tournament_id=? AND y.team_id=m.team_b_id WHERE m.id=?",Integer.class,id,id,matchId);if(ok==null||ok==0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Both match teams must belong to the tournament");ensureFixturePairNotPresent(id,matchId);try{jdbc.update("INSERT INTO tournament_matches(tournament_id,match_id,stage,fixture_number) VALUES (?,?,?,(SELECT COALESCE(MAX(fixture_number),0)+1 FROM tournament_matches WHERE tournament_id=?))",id,matchId,normalizedStage,id);}catch(DataIntegrityViolationException e){throw new ResponseStatusException(HttpStatus.CONFLICT,"Match is already linked to a tournament or fixture number is unavailable");}return fixture(id,matchId);}
 @PostMapping("/{id}/fixtures/generate") @Transactional GenerateFixturesResponse generateFixtures(@PathVariable UUID id,Authentication a){requireOwner(id,a);TournamentView tournament=get(id,a);ensureTournamentEditable(id);List<TeamView> registered=teams(id,a);if(registered.size()<2)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Add at least 2 teams before generating fixtures");String format=tournament.format().trim().toUpperCase(Locale.ROOT);if(!Set.of("T10","T20","ODI","TEST","CUSTOM").contains(format))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Tournament format is not supported for automatic fixture generation");List<Pair> existing=jdbc.query("SELECT m.team_a_id,m.team_b_id FROM tournament_matches tm JOIN matches m ON m.id=tm.match_id WHERE tm.tournament_id=?",(r,n)->new Pair(r.getObject("team_a_id",UUID.class),r.getObject("team_b_id",UUID.class)),id);Set<String> existingPairs=new HashSet<>();for(Pair p:existing)existingPairs.add(pairKey(p.a(),p.b()));int nextFixture=Optional.ofNullable(jdbc.queryForObject("SELECT MAX(fixture_number) FROM tournament_matches WHERE tournament_id=?",Integer.class,id)).orElse(0)+1;int generated=0,skipped=0;for(int i=0;i<registered.size();i++)for(int j=i+1;j<registered.size();j++){TeamView home=registered.get(i),away=registered.get(j);String key=pairKey(home.id(),away.id());if(existingPairs.contains(key)){skipped++;continue;}UUID matchId=UUID.randomUUID();String matchName="Fixture "+nextFixture+": "+home.name()+" vs "+away.name();jdbc.update("INSERT INTO matches(id,name,team_a_id,team_b_id,format,total_overs,scheduled_at,status) VALUES (?,?,?,?,?,?,?, 'SCHEDULED')",matchId,matchName,home.id(),away.id(),format,tournament.overs(),null);jdbc.update("INSERT INTO tournament_matches(tournament_id,match_id,stage,fixture_number) VALUES (?,?, 'LEAGUE', ?)",id,matchId,nextFixture);existingPairs.add(key);nextFixture++;generated++;}return new GenerateFixturesResponse(id,generated,skipped,generated+skipped,fixtures(id,a));}
 @GetMapping("/{id}/fixtures") List<FixtureView> fixtures(@PathVariable UUID id,Authentication a){requireOwner(id,a);return jdbc.query("SELECT tm.match_id,tm.fixture_number,tm.stage,m.name,m.team_a_id,x.name team_a_name,m.team_b_id,y.name team_b_name,m.status,m.scheduled_at FROM tournament_matches tm JOIN matches m ON m.id=tm.match_id JOIN teams x ON x.id=m.team_a_id JOIN teams y ON y.id=m.team_b_id WHERE tm.tournament_id=? ORDER BY COALESCE(tm.fixture_number,999999),m.scheduled_at NULLS LAST",(r,n)->new FixtureView(r.getObject("match_id",UUID.class),r.getObject("fixture_number",Integer.class),r.getString("stage"),r.getString("name"),r.getObject("team_a_id",UUID.class),r.getString("team_a_name"),r.getObject("team_b_id",UUID.class),r.getString("team_b_name"),r.getString("status"),r.getObject("scheduled_at")==null?null:r.getObject("scheduled_at").toString()),id);}
 @PostMapping("/{id}/fixtures/{matchId}/schedule") FixtureView schedule(@PathVariable UUID id,@PathVariable UUID matchId,@Valid @RequestBody ScheduleRequest q,Authentication a){requireOwner(id,a);ensureTournamentNotCompleted(id);if(q.scheduledAt().isBefore(OffsetDateTime.now().minusMinutes(1)))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Fixture time must be in the future");Integer linked=jdbc.queryForObject("SELECT COUNT(*) FROM tournament_matches WHERE tournament_id=? AND match_id=?",Integer.class,id,matchId);if(linked==null||linked==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Fixture is not linked to this tournament");Integer conflict=jdbc.queryForObject("SELECT COUNT(*) FROM matches existing WHERE existing.scheduled_at=? AND existing.status IN ('SCHEDULED','LIVE') AND existing.id<>? AND (existing.team_a_id IN (SELECT candidate.team_a_id FROM matches candidate WHERE candidate.id=? UNION SELECT candidate.team_b_id FROM matches candidate WHERE candidate.id=?) OR existing.team_b_id IN (SELECT candidate.team_a_id FROM matches candidate WHERE candidate.id=? UNION SELECT candidate.team_b_id FROM matches candidate WHERE candidate.id=?) OR EXISTS (SELECT 1 FROM tournament_matches linked WHERE linked.match_id=existing.id AND linked.tournament_id=?))",Integer.class,q.scheduledAt(),matchId,matchId,matchId,matchId,matchId,id);if(conflict!=null&&conflict>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"A team or tournament already has a scheduled/live fixture at this exact time");jdbc.update("UPDATE matches SET scheduled_at=?, status=CASE WHEN status='COMPLETED' THEN status ELSE 'SCHEDULED' END WHERE id=?",q.scheduledAt(),matchId);return fixture(id,matchId);}
 @GetMapping("/{id}/points-table") List<PointRow> points(@PathVariable UUID id,Authentication a){
  requireOwner(id,a);
  List<TournamentStandingsCalculator.Team> registered=teams(id,a).stream()
    .map(t->new TournamentStandingsCalculator.Team(t.id(),t.name())).toList();
  List<TournamentStandingsCalculator.Match> completed=jdbc.query("""
    SELECT m.team_a_id,m.team_b_id,m.status,m.result_type,
           COALESCE(m.winning_team_id,m.winner_team_id) AS winner_team_id,m.total_overs,
           i1.batting_team_id AS i1_team,i1.total_runs AS i1_runs,i1.wickets AS i1_wickets,
           i1.legal_balls AS i1_balls,i1.total_overs AS i1_overs,
           i2.batting_team_id AS i2_team,i2.total_runs AS i2_runs,i2.wickets AS i2_wickets,
           i2.legal_balls AS i2_balls,i2.total_overs AS i2_overs
    FROM tournament_matches tm
    JOIN matches m ON m.id=tm.match_id
    LEFT JOIN innings i1 ON i1.match_id=m.id AND i1.innings_number=1 AND i1.is_super_over=FALSE
    LEFT JOIN innings i2 ON i2.match_id=m.id AND i2.innings_number=2 AND i2.is_super_over=FALSE
    WHERE tm.tournament_id=? AND COALESCE(tm.stage,'LEAGUE')='LEAGUE'
      AND m.status='COMPLETED'
    """,(r,n)->new TournamentStandingsCalculator.Match(
      r.getObject("team_a_id",UUID.class),r.getObject("team_b_id",UUID.class),
      r.getString("status"),r.getString("result_type"),r.getObject("winner_team_id",UUID.class),
      r.getObject("total_overs",Integer.class),
      new TournamentStandingsCalculator.Innings(r.getObject("i1_team",UUID.class),r.getInt("i1_runs"),
        r.getInt("i1_wickets"),r.getInt("i1_balls"),r.getObject("i1_overs",Integer.class)),
      new TournamentStandingsCalculator.Innings(r.getObject("i2_team",UUID.class),r.getInt("i2_runs"),
        r.getInt("i2_wickets"),r.getInt("i2_balls"),r.getObject("i2_overs",Integer.class))
    ),id);
  return TournamentStandingsCalculator.calculate(registered,completed).stream()
    .map(s->new PointRow(s.teamId(),s.teamName(),s.played(),s.wins(),s.losses(),s.ties(),
      s.noResults(),s.points(),s.runsFor(),s.runsAgainst(),s.nrr())).toList();
 }
 @GetMapping("/{id}/qualification") QualificationPreview qualification(@PathVariable UUID id,Authentication a){requireOwner(id,a);List<PointRow> table=points(id,a);if(table.size()<4)return new QualificationPreview(false,"At least 4 tournament teams are required for a top-4 qualification bracket.",table,List.of());List<Qualifier> qualifiers=List.of(new Qualifier(1,"QUALIFIER 1",table.get(0),table.get(1)),new Qualifier(2,"ELIMINATOR",table.get(2),table.get(3)));return new QualificationPreview(true,"Top 4 are currently projected to qualify based on points, NRR, runs-for and team name.",table,qualifiers);}
 @PostMapping("/{id}/playoffs/progress") @Transactional TournamentPlayoffService.PlayoffProgressResponse progressPlayoffs(@PathVariable UUID id,Authentication a){requireOwner(id,a);return playoffService.advance(id,()->points(id,a));}
 private FixtureView fixture(UUID tid,UUID mid){return jdbc.queryForObject("SELECT tm.match_id,tm.fixture_number,tm.stage,m.name,m.team_a_id,x.name team_a_name,m.team_b_id,y.name team_b_name,m.status,m.scheduled_at FROM tournament_matches tm JOIN matches m ON m.id=tm.match_id JOIN teams x ON x.id=m.team_a_id JOIN teams y ON y.id=m.team_b_id WHERE tm.tournament_id=? AND tm.match_id=?",(r,n)->new FixtureView(r.getObject("match_id",UUID.class),r.getObject("fixture_number",Integer.class),r.getString("stage"),r.getString("name"),r.getObject("team_a_id",UUID.class),r.getString("team_a_name"),r.getObject("team_b_id",UUID.class),r.getString("team_b_name"),r.getString("status"),r.getObject("scheduled_at")==null?null:r.getObject("scheduled_at").toString()),tid,mid);}
 private void validateTransition(String current,String target,UUID id){if(current==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Tournament not found");if(current.equals(target))throw new ResponseStatusException(HttpStatus.CONFLICT,"Tournament is already "+target);if("DRAFT".equals(current)&&"ACTIVE".equals(target)){Integer teamCount=jdbc.queryForObject("SELECT COUNT(*) FROM tournament_teams WHERE tournament_id=?",Integer.class,id);Integer fixtureCount=jdbc.queryForObject("SELECT COUNT(*) FROM tournament_matches WHERE tournament_id=?",Integer.class,id);if(teamCount==null||teamCount<2)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"At least 2 teams are required before activating the tournament");if(fixtureCount==null||fixtureCount<1)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Generate or add at least 1 fixture before activating the tournament");return;}if("ACTIVE".equals(current)&&"COMPLETED".equals(target)){Integer total=jdbc.queryForObject("SELECT COUNT(*) FROM tournament_matches WHERE tournament_id=?",Integer.class,id);Integer completed=jdbc.queryForObject("SELECT COUNT(*) FROM tournament_matches tm JOIN matches m ON m.id=tm.match_id WHERE tm.tournament_id=? AND m.status='COMPLETED'",Integer.class,id);if(total==null||total<1)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Tournament has no fixtures to complete");if(!Objects.equals(total,completed))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"All tournament fixtures must be completed before completing the tournament");return;}throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid tournament status transition: "+current+" -> "+target);}
 private void ensureTournamentEditable(UUID id){String status=jdbc.queryForObject("SELECT status FROM tournaments WHERE id=?",String.class,id);if(!"DRAFT".equals(status))throw new ResponseStatusException(HttpStatus.CONFLICT,"Tournament can only be edited while in DRAFT status");}
 void ensureFixturePairNotPresent(UUID tournamentId,UUID matchId){
  Integer duplicate=jdbc.queryForObject("SELECT COUNT(*) FROM tournament_matches tm JOIN matches existing ON existing.id=tm.match_id JOIN matches candidate ON candidate.id=? WHERE tm.tournament_id=? AND ((existing.team_a_id=candidate.team_a_id AND existing.team_b_id=candidate.team_b_id) OR (existing.team_a_id=candidate.team_b_id AND existing.team_b_id=candidate.team_a_id))",Integer.class,matchId,tournamentId);
  if(duplicate!=null&&duplicate>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"A fixture for this team pair already exists in this tournament");
 }
 void ensureTeamCanBeRemoved(UUID tournamentId,UUID teamId){Integer fixtures=jdbc.queryForObject("SELECT COUNT(*) FROM tournament_matches tm JOIN matches m ON m.id=tm.match_id WHERE tm.tournament_id=? AND (m.team_a_id=? OR m.team_b_id=?)",Integer.class,tournamentId,teamId,teamId);if(fixtures!=null&&fixtures>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Team cannot be removed after tournament fixtures have been created; remove or reset those fixtures first");}
 private void ensureTournamentNotCompleted(UUID id){String status=jdbc.queryForObject("SELECT status FROM tournaments WHERE id=?",String.class,id);if("COMPLETED".equals(status))throw new ResponseStatusException(HttpStatus.CONFLICT,"Completed tournament cannot be rescheduled");}
 private UUID ownerId(Authentication a){try{return jdbc.queryForObject("SELECT id FROM users WHERE LOWER(TRIM(email))=LOWER(TRIM(?)) OR CAST(id AS TEXT)=?",UUID.class,a.getName(),a.getName());}catch(Exception e){throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"User not found");}}
 private void requireOwner(UUID id,Authentication a){UUID userId=ownerId(a);Integer n=jdbc.queryForObject("SELECT COUNT(*) FROM tournaments t WHERE t.id=? AND (t.owner_id=? OR EXISTS (SELECT 1 FROM tournament_staff ts WHERE ts.tournament_id=t.id AND ts.user_id=? AND ts.role='MANAGER'))",Integer.class,id,userId,userId);if(n==null||n==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Tournament not found");}
 private static double calculateNrr(int runsFor,int runsAgainst,double ballsFor,double ballsAgainst){if(ballsFor<=0||ballsAgainst<=0)return 0.0;double nrr=(runsFor/(ballsFor/6.0))-(runsAgainst/(ballsAgainst/6.0));return Math.round(nrr*1000.0)/1000.0;}
 private static String normalizeStage(String stage){String normalized=stage==null?"LEAGUE":stage.trim().toUpperCase(Locale.ROOT);if(!Set.of("LEAGUE","QUALIFIER","QUALIFIER_1","QUALIFIER_2","ELIMINATOR","SEMI_FINAL","FINAL","THIRD_PLACE","SUPER_OVER").contains(normalized))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unsupported tournament stage: "+normalized);return normalized;}
 private static String blank(String s){return s==null||s.isBlank()?null:s.trim();}
 private static String pairKey(UUID a,UUID b){return a.compareTo(b)<0?a+":"+b:b+":"+a;}
 public record CreateRequest(@NotBlank String name,@NotBlank String format,@Positive int overs,String location,LocalDate startDate){}
 public record UpdateRequest(@jakarta.validation.constraints.Size(min=3,max=90) @NotBlank String name,@NotBlank String format,@jakarta.validation.constraints.Min(1) @jakarta.validation.constraints.Max(100) int overs,@jakarta.validation.constraints.Size(max=120) String location,LocalDate startDate){}
 public record StatusRequest(@NotBlank String status){}
 public record ScheduleRequest(@jakarta.validation.constraints.NotNull OffsetDateTime scheduledAt){}
 public record TournamentView(UUID id,String name,String format,int overs,String location,LocalDate startDate,String status,String createdAt){}
 public record TeamView(UUID id,String name,String city,Integer seed){}
 public record FixtureView(UUID matchId,Integer fixtureNumber,String stage,String matchName,UUID teamAId,String teamAName,UUID teamBId,String teamBName,String status,String scheduledAt){}
 public record GenerateFixturesResponse(UUID tournamentId,int generated,int skipped,int totalPairs,List<FixtureView> fixtures){}
 public record PointRow(UUID teamId,String teamName,int played,int wins,int losses,int ties,int noResults,int points,int runsFor,int runsAgainst,double nrr){}
 public record QualificationPreview(boolean eligible,String message,List<PointRow> table,List<Qualifier> qualifiers){}
 public record Qualifier(int seed,String label,PointRow higherSeed,PointRow lowerSeed){}
 private record MatchScore(UUID id,UUID iaTeam,int iaRuns,int iaBalls,UUID ibTeam,int ibRuns,int ibBalls){}
 private record Pair(UUID a,UUID b){}
}
